class Solution:
    def balancedStringSplit(self, s: str) -> int:
        ans, start = 0, 0
        for i in range(len(s)):
            if s[start:i+1].count('L') == s[start:i+1].count('R'):
                ans += 1
                start = i + 1
        return ans

