class Solution {
public:
    int balancedStringSplit(string s) {
        int ans = 0, start = 0;
        for (int i = 0; i < (int)s.size(); i++) {
            int l = 0, r = 0;
            for (int j = start; j <= i; j++) s[j] == 'L' ? l++ : r++;
            if (l == r) { ans++; start = i + 1; }
        }
        return ans;
    }
};

