var balancedStringSplit = function(s) {
    let ans = 0, start = 0;
    for (let i = 0; i < s.length; i++) {
        let seg = s.slice(start, i + 1);
        let l = [...seg].filter(c => c === 'L').length;
        let r = seg.length - l;
        if (l === r) { ans++; start = i + 1; }
    }
    return ans;
};

